window.GRIMORIO_PARAPRISMATIC_SPELL_GROUPS = [{"id":"elemental-confluence","name":"Confluência Elemental","originalName":"Elemental Confluence","page":49,"description":"Qualquer magia listada como Elemental Confluence é considerada simultaneamente parte de Burning Rites, Harvest Tradition, Torrential Arcanics e Twisting Gale Path. A frase introdutória da fonte imprime “Harvest Manual”; o nome usado pelo grupo no restante do livro é Harvest Tradition.","spells":["Absorb Energy","Cataclysm","Chromatic Arrow","Chaos Burst","Conjure Elemental Avatar","Control Weather","Elemental Assault","Energy Scourge","Grand Elemental Aspect","Infused Weapon","Plane Shift","Prismatic Spray","Tempest Strikes","Tempest Ward","Wyrm’s Breath"]},{"id":"burning-rites","name":"Ritos Ardentes","originalName":"Burning Rites","page":49,"description":"Magias nascidas do poder de Burtromet, associadas a fogo e ferro.","spells":["Burning Ammunition","Burning Hands","Burning Web","Fire Bolt","Fire Shield","Fire Storm","Fire Whip","Fireball","Flame Blade","Flame Strike","Flaming Sphere","Forgelord’s Chains","Heat Metal","Hellish Rebuke","Igniting Smite","Incendiary Cloud","Incineration Tower","Investiture of Fire","Magic Weapon","Magma Wave","Manipulate Flames","Mending","Minute Meteors","Nova","Produce Flame","Saint’s Hallowing","Scorching Ray","Scorching Wave","Sear","Volcanic Ash","Vorpal Flames","Wall of Fire"]},{"id":"harvest-tradition","name":"Tradição da Colheita","originalName":"Harvest Tradition","page":50,"description":"Magias vinculadas a Tithiss, à terra e às plantas. Binding Vine e Ivy Whip são nomes alterados e não são reescritas no livro por não estarem no SRD, conforme nota da própria fonte.","spells":["Artemina’s Hunting Bow","Barkskin","Binding Vine","Cloudkill","Commune with Nature","Create Food and Water","Create or Destroy Water","Detect Poison and Disease","Druidcraft","Dust Twister","Earth Geyser","Earthen Eruption","Earthen Grasp","Earthquake","Elstrakin’s Instant Bounty","Entangle","Free Meadow","Gaius Avatar","Gentle Repose","Investiture of Earth","Ivy Whip","Land’s Fury","Lashing Willow","Manipulate Earth","Move Earth","Place of Protection","Plant Growth","Protection from Poison","Ray of Sickness","Shillelagh","Speak with Plants","Stone Shape","Stoneskin","Transport via Plants","Tree Stride","Wall of Thorns"]},{"id":"torrential-arcanics","name":"Arcanias Torrenciais","originalName":"Torrential Arcanics","page":50,"description":"Poderes derivados de Ilsrabae, associados a gelo, água e criaturas marinhas.","spells":["Acid Arrow","Acid Splash","Black Tentacles","Create Food and Water","Create or Destroy Water","Cone of Cold","Control Water","Corrosive Smite","Drowning Wave","Freezing Sphere","Frostveil","Fog Cloud","Hydro Cage","Hydro Wall","Ice Storm","Ilsrabae’s Veil","Investiture of Frost","Manipulate Water","Piercing Crystal","Protection from Poison","Ray of Frost","Sea-Dweller’s Aspect","Silencing Smite","Sleet Storm","Snowball Storm","Tsunami","Wall of Ice","Water Breathing","Water Walk","Whirlpool"]},{"id":"twisting-gale-path","name":"Caminho do Vendaval","originalName":"Twisting Gale Path","page":50,"description":"Magias concedidas pelo poder de Ivsil, principalmente destrutivas e ligadas a vento e eletricidade.","spells":["Battering Storm","Billow","Blur","Chain Lightning","Conquering Winds","Electric Arc","Electric Chain","Feather Fall","Fly","Gust of Wind","Harpy Strike","Hunter’s Mark","Investiture of Air","Laborious Flight","Lightning Bolt","Lightning Hurl","Lightning Storm","Longstrider","Protective Gale","Seizing Bolt","Shocking Grasp","Slash Wind","Thunderwave","Tornado","Vortex Quiver","Wind Walk"]}];

window.GRIMORIO_PARAPRISMATIC_SPELLS = [{"id":"paraprismatic-battering-storm","name":"Tempestade Avassaladora","originalName":"Battering Storm","aliases":[],"level":4,"school":"Evocação","time":"1 ação","range":"45 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Uma esfera de ar giratório com 6 metros de raio surge centrada em um ponto que você escolher dentro do alcance e permanece pela duração. Cada criatura que estiver na esfera quando ela surgir ou que terminar o turno nela deve ser bem-sucedida em um teste de resistência de Força ou sofre 2d6 de dano contundente. O espaço da esfera é terreno difícil.\n\nAté a magia terminar, você pode usar uma ação bônus em cada um de seus turnos para fazer um raio saltar do centro da esfera em direção a uma criatura à sua escolha a até 18 metros do centro. Faça um ataque à distância com magia. Você tem vantagem na jogada de ataque se o alvo estiver dentro da esfera. Em um acerto, o alvo sofre 4d6 de dano elétrico.\n\nCriaturas a até 9 metros da esfera têm desvantagem em testes de Sabedoria (Percepção) feitos para ouvir.","higher":"Quando você conjura esta magia usando um espaço de 5º nível ou superior, o dano de cada um de seus efeitos aumenta em 1d6 para cada nível do espaço acima do 4º.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":51,"category":"Paraprismatic Tempest","traits":["Twisting Gale Path"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-billow","name":"Lufada","originalName":"Billow","aliases":[],"level":0,"school":"Transmutação","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você toma controle do ar e o força a criar um dos efeitos a seguir em um ponto que possa ver dentro do alcance:\n• Uma criatura Média ou menor à sua escolha deve ser bem-sucedida em um teste de resistência de Força ou é empurrada até 1,5 metro para longe de você.\n• Você cria uma pequena explosão de ar capaz de mover um objeto que não esteja sendo vestido nem carregado e que pese no máximo 2,25 kg. O objeto é empurrado até 3 metros para longe de você. Ele não é empurrado com força suficiente para causar dano.\n• Você cria um efeito sensorial inofensivo usando o ar, como fazer folhas farfalharem, o vento bater persianas ou suas roupas ondularem em uma brisa.","higher":"","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":51,"category":"Paraprismatic Tempest","traits":["Twisting Gale Path"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-cataclysm","name":"Cataclismo","originalName":"Cataclysm","aliases":[],"level":9,"school":"Evocação","time":"1 ação","range":"90 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Clérigo, Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você conjura uma explosão apocalíptica de energia que causa um tipo de dano de tempestade à sua escolha e desaba sobre uma esfera de 12 metros de raio centrada em um ponto escolhido dentro do alcance. Cada criatura nesse espaço deve realizar um teste de resistência determinado pelo tipo de dano escolhido, sofrendo 30d12 desse dano em uma falha, ou metade em um sucesso. Resistências a tipos de dano de tempestade e Limiares de Dano são ignorados por esta magia.\n\nÁcido (salvaguarda de Destreza). Uma onda abrasadora de ácido percorre a área, rodopiando e perseguindo os que estão dentro dela. Cada criatura que falhar tem suas armaduras, equipamentos e armas não mágicos destruídos ou corroídos, tornando-os inúteis. Criaturas compostas majoritariamente por materiais inorgânicos sofrem 5d12 de dano adicional em uma falha, ou metade em um sucesso.\n\nFrio (salvaguarda de Constituição). A área é envolta em uma corrente de névoa congelante, que então se cristaliza em um enorme bloco de gelo e se despedaça. Cada alvo que falhar fica Lento (Sluggish) e repete a salvaguarda ao final de cada um de seus turnos, encerrando o efeito em um sucesso. Criaturas ao menos metade submersas em líquido ou compostas de líquido sofrem 5d12 de dano adicional em uma falha, ou metade em um sucesso.\n\nFogo (salvaguarda de Destreza). Uma explosão meteórica de chamas cai sobre a área, queimando tudo em um clarão celestial. Cada alvo que falhar fica Incendiado (Ignited; 4d6 de dano de fogo) e só pode apagar as chamas usando uma ação para se submergir completamente em líquido ou realizando um teste de Destreza contra sua CD de magia para rolar agressivamente e apagá-las. Criaturas vestindo ou compostas por materiais altamente inflamáveis sofrem 5d12 de dano adicional em uma falha, ou metade em um sucesso.\n\nElétrico (salvaguarda de Destreza). Relâmpagos saltam de criatura em criatura e então explodem em uma descarga selvagem de energia bruta. Cada alvo que falhar fica paralisado e realiza uma salvaguarda de Constituição ao final de cada um de seus turnos, encerrando o efeito em um sucesso. Criaturas usando armadura média ou pesada de metal, ou compostas ao menos parcialmente de metal, sofrem 5d12 de dano adicional em uma falha, ou metade em um sucesso.\n\nVeneno (salvaguarda de Constituição). Um miasma mortal atravessa o raio da magia, invadindo agressivamente os corpos dentro dele. Cada criatura que falhar fica envenenada e, enquanto estiver envenenada dessa forma, sofre 4d6 de dano de veneno no início de cada um de seus turnos. Ela repete a salvaguarda ao final de cada turno, encerrando o efeito em um sucesso. Criaturas que falharem por 5 pontos ou mais sofrem 5d12 de dano adicional em uma falha, ou metade em um sucesso.\n\nConhecimento Tempestuoso. Quando você aprende esta magia ou escolhe prepará-la, escolha um tipo de dano de tempestade. Sempre que a magia mencionar dano de tempestade, ela causa o tipo escolhido. Você pode aprender ou preparar esta magia várias vezes, escolhendo um tipo diferente em cada vez, e usar essas opções quando ela se referir a dano de tempestade.","higher":"","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":52,"category":"Paraprismatic Tempest","traits":["Elemental Confluence"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-conjure-elemental-avatar","name":"Conjurar Avatar Elemental","originalName":"Conjure Elemental Avatar","aliases":[],"level":5,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (uma gema no valor de pelo menos 500 po)","material":"uma gema no valor de pelo menos 500 po","duration":"Concentração, até 1 hora","classes":"Druida, Inscritor, Cavaleiro das Pétalas, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você invoca o eco de um avatar elemental, que se manifesta em um espaço desocupado que você possa ver dentro do alcance. O elemental usa o bloco de estatísticas Modelo do Avatar Elemental. Ao invocá-lo, escolha ar, terra, fogo ou água, opção que determina parte de suas características. O elemental desaparece quando é reduzido a 0 pontos de vida ou quando a magia termina.\n\nO tipo escolhido determina o tipo de dano do elemental: Ar — elétrico; Terra — contundente; Fogo — fogo; Água — frio.\n\nO avatar elemental é aliado seu e de seus companheiros. Ele compartilha sua contagem de iniciativa, mas realiza o turno imediatamente após o seu. Obedece a seus comandos verbais sem exigir ação sua; se você não der comandos, ele realiza a ação Esquivar e usa o movimento para evitar perigo.\n\nModelo do Avatar Elemental (p. 53). Elemental Grande. CA 10 + modificador de Destreza + nível da magia. PV 10 × nível da magia. Deslocamento 15 m; escavação 15 m (terra); voo (pairar) 27 m (ar); natação 27 m (água). FOR 16, DES 18, CON 16, INT 6, SAB 10, CAR 7. Resistências: contundente, perfurante e cortante de ataques não mágicos. Imunidades: ácido (terra), frio (água), fogo (fogo), elétrico (ar), veneno; exausto, agarrado, paralisado, petrificado, envenenado, caído, impedido e inconsciente. Sentidos: visão no escuro 18 m; visão às cegas 18 m (ar ou água); visão no escuro 36 m (fogo); sentido sísmico 18 m (terra); Percepção passiva 10. Idiomas: entende os idiomas do conjurador, mas não fala.\n\nForma Ardente (Fogo). Pode atravessar espaços de 2,5 cm sem se espremer. Uma criatura que o toque ou o atinja com um ataque corpo a corpo a até 1,5 m sofre dano de fogo igual a 1d10 + o nível da magia que o conjurou. O avatar pode entrar no espaço de uma criatura hostil e parar ali; na primeira vez em seu turno que entra no espaço de uma criatura, ela sofre esse dano e fica Incendiada. Emite luz plena em 9 m e penumbra por mais 9 m.\n\nForma da Terra (Terra). Pode escavar através de terra e pedra não mágicas e não trabalhadas sem perturbar o material. Seus ataques Golpe da Tempestade causam 2d6 de dano adicional e ele possui Limiar de Dano igual a 5 + o nível em que a magia foi conjurada.\n\nArmas Mágicas. Os ataques do avatar são mágicos.\n\nMudança de Tamanho. É invocado como Enorme por um espaço de 7º nível ou superior e como Colossal no 9º nível; seu alcance aumenta em 1,5 m em cada um desses patamares.\n\nForma da Tempestade (Ar). Pode atravessar espaços de 2,5 cm sem se espremer. Uma criatura que o toque ou o atinja com ataque corpo a corpo a até 1,5 m sofre dano elétrico igual a 1d10 + o nível da magia. Pode entrar no espaço de criatura hostil e parar ali; na primeira vez em seu turno que entra no espaço de uma criatura, ela sofre esse dano. Ataques contra uma criatura completamente sobreposta por ele têm vantagem.\n\nForma da Água (Água). Pode atravessar espaços de 2,5 cm sem se espremer. Uma criatura que o toque ou o atinja com ataque corpo a corpo a até 1,5 m sofre dano de frio igual a 1d10 + o nível da magia. Pode entrar no espaço de criatura hostil e parar ali; na primeira vez em seu turno que entra no espaço de uma criatura, ela sofre esse dano e fica surda enquanto compartilhar completamente o espaço com ele.\n\nAtaques Múltiplos. O elemental realiza um número de ataques igual à metade do nível da magia e então usa Explosão da Tempestade.\n\nGolpe da Tempestade. Ataque Corpo a Corpo com Arma: seu modificador de ataque com magia para acertar, alcance 3 m, um alvo. Acerto: 2d6 + 4 + o nível da magia, do tipo de dano do avatar.\n\nExplosão da Tempestade. O avatar libera energia elemental, afetando cada criatura dentro de seu alcance corpo a corpo ou em um cone de comprimento igual ao dobro desse alcance. Cada criatura faz uma salvaguarda — Destreza para ar ou fogo, Constituição para terra ou água — contra sua CD de magia; em uma falha, sofre dano do tipo do avatar igual a 1d6 × o nível em que a magia foi conjurada.","higher":"Quando você conjura esta magia no 6º nível ou superior, as estatísticas do avatar mudam conforme descrito no bloco de estatísticas.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":52,"category":"Paraprismatic Tempest","traits":["Elemental Confluence"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. O bloco completo Elemental Avatar Template da página 53 foi incorporado à entrada.","sourcePages":"52–53","summonTemplate":{"name":"Modelo do Avatar Elemental","originalName":"Elemental Avatar Template","size":"Grande","type":"elemental","ac":"10 + modificador de Destreza + nível da magia","hp":"10 × nível da magia","speed":"15 m; escavação 15 m (terra); voo (pairar) 27 m (ar); natação 27 m (água)","abilities":{"str":16,"dex":18,"con":16,"int":6,"wis":10,"cha":7},"resistances":"contundente, perfurante e cortante de ataques não mágicos","immunities":"ácido (terra), frio (água), fogo (fogo), elétrico (ar), veneno; exausto, agarrado, paralisado, petrificado, envenenado, caído, impedido, inconsciente","senses":"visão no escuro 18 m; visão às cegas 18 m (ar ou água); visão no escuro 36 m (fogo); sentido sísmico 18 m (terra); Percepção passiva 10","languages":"entende os idiomas de seu conjurador, mas não fala","traits":[{"name":"Forma Ardente (Fogo)","text":"Pode atravessar espaços de 2,5 cm sem se espremer. Uma criatura que o toque ou o atinja com um ataque corpo a corpo a até 1,5 m sofre dano de fogo igual a 1d10 + o nível da magia que o conjurou. O avatar pode entrar no espaço de uma criatura hostil e parar ali; na primeira vez em seu turno que entra no espaço de uma criatura, ela sofre esse dano e fica Incendiada. Emite luz plena em 9 m e penumbra por mais 9 m."},{"name":"Forma da Terra (Terra)","text":"Pode escavar através de terra e pedra não mágicas e não trabalhadas sem perturbar o material. Seus ataques Golpe da Tempestade causam 2d6 de dano adicional e ele possui Limiar de Dano igual a 5 + o nível em que a magia foi conjurada."},{"name":"Armas Mágicas","text":"Os ataques do avatar são mágicos."},{"name":"Mudança de Tamanho","text":"O avatar é invocado como Enorme quando a magia usa um espaço de 7º nível ou superior e como Colossal no 9º nível. Seu alcance de ataque aumenta em 1,5 m em cada um desses patamares."},{"name":"Forma da Tempestade (Ar)","text":"Pode atravessar espaços de 2,5 cm sem se espremer. Uma criatura que o toque ou o atinja com um ataque corpo a corpo a até 1,5 m sofre dano elétrico igual a 1d10 + o nível da magia. Pode entrar no espaço de uma criatura hostil e parar ali; na primeira vez em seu turno que entra no espaço de uma criatura, ela sofre esse dano. Ataques contra uma criatura completamente sobreposta por ele têm vantagem."},{"name":"Forma da Água (Água)","text":"Pode atravessar espaços de 2,5 cm sem se espremer. Uma criatura que o toque ou o atinja com um ataque corpo a corpo a até 1,5 m sofre dano de frio igual a 1d10 + o nível da magia. Pode entrar no espaço de uma criatura hostil e parar ali; na primeira vez em seu turno que entra no espaço de uma criatura, ela sofre esse dano e fica surda enquanto compartilhar o espaço com o avatar, desde que o espaço esteja completamente coberto."}],"actions":[{"name":"Ataques Múltiplos","text":"O elemental realiza um número de ataques igual à metade do nível da magia e então usa Explosão da Tempestade."},{"name":"Golpe da Tempestade","text":"Ataque Corpo a Corpo com Arma: seu modificador de ataque com magia para acertar, alcance 3 m, um alvo. Acerto: 2d6 + 4 + o nível da magia, do tipo de dano do avatar."},{"name":"Explosão da Tempestade","text":"O avatar libera energia elemental que afeta cada criatura dentro de seu alcance corpo a corpo ou em um cone de comprimento igual ao dobro desse alcance. Cada criatura faz uma salvaguarda — Destreza para ar ou fogo, Constituição para terra ou água — contra sua CD de magia e sofre, em uma falha, dano do tipo do avatar igual a 1d6 × o nível em que a magia foi conjurada."}]}},{"id":"paraprismatic-dust-twister","name":"Redemoinho de Poeira","originalName":"Dust Twister","aliases":[],"level":2,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (uma pitada de poeira)","material":"uma pitada de poeira","duration":"Concentração, até 1 minuto","classes":"Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Escolha um cubo de ar desocupado de 1,5 metro que você possa ver dentro do alcance. Uma força elemental semelhante a um redemoinho de poeira e detritos, aproximadamente na forma de um corruptor rodopiante, aparece no cubo e permanece pela duração.\n\nQualquer criatura que terminar o turno a até 1,5 metro do redemoinho deve realizar uma salvaguarda de Força. Em uma falha, sofre 1d8 de dano contundente e é empurrada 3 metros para longe do redemoinho. Em um sucesso, sofre metade do dano e não é empurrada.\n\nComo ação bônus, você pode mover o redemoinho até 9 metros em qualquer direção. Se ele se mover sobre areia, poeira, terra solta ou cascalho leve, suga o material e forma ao redor de si uma nuvem de detritos com 3 metros de raio, que dura até o início do seu próximo turno. A nuvem deixa a área fortemente obscurecida.","higher":"Quando você conjura esta magia no 4º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 2º:\n• O dano da magia aumenta em 1d8.\n• O alvo é empurrado 3 metros adicionais.\n• O tamanho do cubo dobra.\n• (2 níveis) Uma vez em cada um de seus turnos, você pode mover o redemoinho sem usar sua ação bônus, desde que não esteja incapacitado.\n• (3 níveis) Você não precisa se concentrar nesta magia e pode encerrá-la como ação bônus.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":54,"category":"Paraprismatic Tempest","traits":["Harvest Tradition"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-elemental-assault","name":"Ataque Elemental","originalName":"Elemental Assault","aliases":[],"level":5,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Druida, Paladino, Cavaleiro das Pétalas, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você cria uma explosão fortificada e condensada de um tipo de energia, que ataca um alvo que você possa ver dentro do alcance como um ataque corpo a corpo com magia se ele estiver a até 3 metros, ou como ataque à distância com magia se estiver mais longe. Em um acerto, o alvo sofre 10d10 de dano de tempestade.\n\nConhecimento Tempestuoso. Quando você aprende esta magia ou escolhe prepará-la, escolha um tipo de dano de tempestade. Sempre que a magia mencionar dano de tempestade, ela causa o tipo escolhido. Você pode aprender ou preparar esta magia várias vezes, escolhendo um tipo diferente em cada vez, e usar essas opções quando ela se referir a dano de tempestade.","higher":"Quando você conjura esta magia no 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 5º:\n• O dano aumenta em 2d10.\n• O alcance dobra.\n• Você pode alterar o dano da magia para um tipo de dano de tempestade diferente mesmo que não tenha aprendido/preparado essa versão.\n• (2 níveis) Você pode escolher uma segunda criatura dentro do alcance e realizar uma jogada de ataque com magia separada contra ela.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":54,"category":"Paraprismatic Tempest","traits":["Elemental Confluence"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-freezing-sphere","name":"Esfera Congelante","originalName":"Freezing Sphere","aliases":[],"level":6,"school":"Evocação","time":"1 ação","range":"90 metros","comp":"V, S, M (uma pequena esfera de cristal)","material":"uma pequena esfera de cristal","duration":"Instantânea","classes":"Inscritor, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Um globo gélido de energia fria parte de seus dedos até um ponto à sua escolha dentro do alcance, onde explode em uma esfera de 18 metros de raio. Cada criatura na área deve realizar uma salvaguarda de Constituição. Em uma falha, sofre 10d6 de dano de frio; em um sucesso, metade.\n\nSe o globo atingir um corpo de água ou outro líquido composto principalmente de água, sem incluir criaturas aquáticas, congela o líquido até uma profundidade de 15 cm em uma área quadrada de 9 metros. O gelo dura 1 minuto. Criaturas que estavam nadando na superfície ficam presas no gelo e podem usar uma ação para realizar um teste de Força contra sua CD de magia e se libertar.\n\nVocê pode optar por não disparar o globo após concluir a magia. Um pequeno globo do tamanho de uma pedra de funda, frio ao toque, aparece em sua mão. A qualquer momento, você ou uma criatura à qual entregue o globo pode arremessá-lo até 12 metros ou lançá-lo com uma funda usando o alcance normal da arma. Ele se despedaça no impacto, produzindo o mesmo efeito da conjuração normal. Você também pode pousá-lo sem quebrá-lo. Após 1 minuto, se ainda não tiver se despedaçado, ele explode.","higher":"Quando você conjura esta magia no 7º nível ou superior, ela recebe um dos efeitos a seguir para cada nível acima do 6º:\n• O dano aumenta em 2d6.\n• Criaturas que falharem na salvaguarda ficam presas em gelo e impedidas por 1 minuto; repetem a salvaguarda ao final de cada turno, encerrando o efeito em um sucesso.\n• Você cria dois globos em vez de um, que podem ser disparados imediatamente ou armazenados como descrito acima. Cada globo causa metade da quantidade de dados de dano.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":54,"category":"Paraprismatic Tempest","traits":["Torrential Arcanics","Legado 5.19"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. Esta versão possui alterações mecânicas em relação à magia oficial de mesmo nome e, por isso, permanece como entrada própria em vez de sobrescrever a versão oficial."},{"id":"paraprismatic-frostveil","name":"Véu de Geada","originalName":"Frostveil","aliases":[],"level":0,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você faz uma geada entorpecente se formar sobre uma criatura que possa ver dentro do alcance. O alvo deve realizar uma salvaguarda de Constituição. Em uma falha, sofre 1d6 de dano de frio e tem desvantagem na próxima jogada de ataque com arma que fizer antes do fim do próximo turno.","higher":"Aprimoramento de Truque. O dano aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":55,"category":"Paraprismatic Tempest","traits":["Torrential Arcanics"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-grand-elemental-aspect","name":"Grande Aspecto Elemental","originalName":"Grand Elemental Aspect","aliases":[],"level":8,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Cavaleiro Dracônico, Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você encarna o poder das tempestades. Pela duração, torna-se resistente a todo dano de tempestade, e todo dano de tempestade que causar ignora resistências e Limiares de Dano. Uma vez por turno, quando causar dano como resultado de realizar uma ação, pode causar 5d10 de dano de tempestade adicional a uma criatura que tenha sofrido dano dessa ação. Enquanto estiver sob os efeitos da magia, você também recebe deslocamentos de natação e de voo (pairar) iguais ao dobro do seu deslocamento-base.\n\nEnquanto a magia durar, como ação bônus, você pode escolher uma criatura a até 27 metros e disparar contra ela uma explosão de energia prismática como ataque à distância com magia, causando 6d10 de dano de tempestade em um acerto.\n\nConhecimento Tempestuoso. Quando você aprende esta magia ou escolhe prepará-la, escolha um tipo de dano de tempestade. Sempre que a magia mencionar dano de tempestade, ela causa o tipo escolhido. Você pode aprender ou preparar esta magia várias vezes, escolhendo um tipo diferente em cada vez, e usar essas opções quando ela se referir a dano de tempestade.","higher":"","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":55,"category":"Paraprismatic Tempest","traits":["Elemental Confluence"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-investiture-air","name":"Investidura do Ar","originalName":"Investiture of Air","aliases":[],"level":6,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Até a magia terminar, ventos giram ao seu redor e você recebe os benefícios a seguir:\n• Ataques à distância com arma feitos contra você têm desvantagem.\n• Você ganha deslocamento de voo de 18 metros. Se ainda estiver voando quando a magia terminar, você cai, a menos que consiga evitar a queda.\n• Você pode usar sua ação para criar um cubo de vento giratório de 4,5 metros centrado em um ponto que possa ver a até 18 metros. Cada criatura na área deve realizar uma salvaguarda de Constituição. Uma criatura sofre 2d10 de dano contundente em uma falha, ou metade em um sucesso. Se uma criatura Grande ou menor falhar, também é empurrada até 3 metros para longe do centro do cubo.","higher":"Se você conjurar esta magia no 7º nível ou superior, para cada nível acima do 6º o cubo giratório causa 1d10 de dano contundente adicional, o alcance do cubo pode aumentar em até 3 metros e a categoria máxima de tamanho da criatura empurrada aumenta em uma categoria.\n\nSe conjurada usando um espaço de 9º nível, o deslocamento de voo dobra para 36 metros, todos os ataques feitos contra você têm desvantagem e você pode criar o cubo de vento giratório como ação bônus.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":55,"category":"Paraprismatic Tempest","traits":["Twisting Gale Path","Legado 5.19"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. Esta versão possui alterações mecânicas em relação à magia oficial de mesmo nome e, por isso, permanece como entrada própria em vez de sobrescrever a versão oficial."},{"id":"paraprismatic-investiture-earth","name":"Investidura da Terra","originalName":"Investiture of Earth","aliases":[],"level":6,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Até a magia terminar, fragmentos de rocha se espalham por seu corpo e você recebe os benefícios a seguir:\n• Você tem resistência a dano contundente, perfurante e cortante de ataques não mágicos.\n• Você pode usar sua ação para criar um pequeno terremoto no chão em um raio de 4,5 metros centrado em você. Outras criaturas nesse chão devem ser bem-sucedidas em uma salvaguarda de Destreza ou ficam caídas.\n• Você pode atravessar terreno difícil feito de terra ou pedra sem gastar movimento adicional. Pode atravessar terra ou pedra sólida como se fosse ar, sem desestabilizá-la, mas não pode terminar seu movimento ali. Se fizer isso, é expelido para o espaço desocupado mais próximo, a magia termina e você fica atordoado até o fim do seu próximo turno.","higher":"Quando você conjura esta magia no 7º nível ou superior, para cada nível acima do 6º o raio do terremoto pode ser aumentado ao dobro da distância, dobrando novamente a cada nível. Além disso, para cada nível acima do 6º, criaturas que falharem na salvaguarda sofrem 2d8 de dano de energia em uma falha, ou metade em um sucesso.\n\nQuando conjurada no 9º nível, você se torna imune a dano contundente, perfurante e cortante não mágico.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":55,"category":"Paraprismatic Tempest","traits":["Harvest Tradition","Legado 5.19"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. Esta versão possui alterações mecânicas em relação à magia oficial de mesmo nome e, por isso, permanece como entrada própria em vez de sobrescrever a versão oficial."},{"id":"paraprismatic-investiture-fire","name":"Investidura do Fogo","originalName":"Investiture of Fire","aliases":[],"level":6,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Chamas percorrem seu corpo, emitindo luz plena em um raio de 9 metros e penumbra por mais 9 metros durante a duração. As chamas não ferem você. Até a magia terminar, você recebe os benefícios a seguir:\n• Você é imune a dano de fogo e resistente a dano de frio.\n• Qualquer criatura que se mova para até 1,5 metro de você pela primeira vez em um turno ou termine o turno ali sofre 1d10 de dano de fogo.\n• Você pode usar sua ação para criar uma linha de fogo de 4,5 metros de comprimento e 1,5 metro de largura partindo de você em uma direção à sua escolha. Cada criatura na linha realiza uma salvaguarda de Destreza, sofrendo 4d8 de dano de fogo em uma falha ou metade em um sucesso.","higher":"Quando você conjura esta magia no 7º nível ou superior, para cada nível acima do 6º a linha de fogo aumenta em 3 metros de comprimento, ou você pode dividir o comprimento total em feixes adicionais, cada um com pelo menos 3 metros de comprimento, e o primeiro valor de dano aumenta em 2d8.\n\nSe conjurada no 9º nível, o alcance no qual criaturas sofrem dano desta magia aumenta para 9 metros, ignorando seus aliados, e esse dano aumenta para 2d10.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":56,"category":"Paraprismatic Tempest","traits":["Burning Rites","Legado 5.19"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. Esta versão possui alterações mecânicas em relação à magia oficial de mesmo nome e, por isso, permanece como entrada própria em vez de sobrescrever a versão oficial. A expressão “the first damage” do escalonamento foi mantida sem reinterpretá-la silenciosamente."},{"id":"paraprismatic-investiture-frost","name":"Investidura da Geada","originalName":"Investiture of Frost","aliases":[],"level":6,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Até a magia terminar, gelo cobre seu corpo e você recebe os benefícios a seguir:\n• Você é imune a dano de frio e resistente a dano de fogo.\n• Pode atravessar terreno difícil criado por gelo ou neve sem gastar movimento adicional.\n• O chão em um raio de 3 metros ao seu redor fica congelado e é terreno difícil para criaturas que não sejam você. O raio se move com você.\n• Você pode usar sua ação para criar um cone de vento congelante de 4,5 metros partindo de sua mão estendida. Cada criatura no cone realiza uma salvaguarda de Constituição, sofrendo 4d6 de dano de frio em uma falha ou metade em um sucesso. Uma criatura que falhar tem o deslocamento reduzido à metade até o início do seu próximo turno.","higher":"Quando você conjura esta magia no 7º nível ou superior, para cada nível acima do 6º o cone dobra de comprimento e o dano de frio aumenta em 2d6.\n\nQuando conjurada no 9º nível, criaturas que falharem nessa salvaguarda ficam cobertas de gelo e impedidas até o início do seu próximo turno.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":56,"category":"Paraprismatic Tempest","traits":["Torrential Arcanics","Legado 5.19"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. Esta versão possui alterações mecânicas em relação à magia oficial de mesmo nome e, por isso, permanece como entrada própria em vez de sobrescrever a versão oficial."},{"id":"paraprismatic-lightning-bolt","name":"Relâmpago","originalName":"Lightning Bolt","aliases":[],"level":3,"school":"Evocação","time":"1 ação","range":"Pessoal (linha de 30 metros)","comp":"V, S, M (um pouco de pelo e uma haste de âmbar, cristal ou vidro)","material":"um pouco de pelo e uma haste de âmbar, cristal ou vidro","duration":"Instantânea","classes":"Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Um raio formando uma linha de 30 metros de comprimento e 1,5 metro de largura parte de você em uma direção à sua escolha. Cada criatura na linha deve realizar uma salvaguarda de Destreza, sofrendo 8d6 de dano elétrico em uma falha ou metade em um sucesso. O relâmpago incendeia objetos inflamáveis na área que não estejam sendo vestidos nem carregados.","higher":"Quando você conjura esta magia no 4º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 3º:\n• O dano elétrico aumenta em 1d6.\n• O comprimento da linha aumenta em 15 metros.\n• (2 níveis) Qualquer criatura que falhar na salvaguarda por 5 pontos ou mais fica atordoada até o início do próximo turno.\n• (2 níveis) Você pode disparar um segundo raio idêntico em outra direção. Criaturas atingidas por dois ou mais raios são afetadas apenas uma vez.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":56,"category":"Paraprismatic Tempest","traits":["Twisting Gale Path","Legado 5.19"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. Esta versão possui alterações mecânicas em relação à magia oficial de mesmo nome e, por isso, permanece como entrada própria em vez de sobrescrever a versão oficial."},{"id":"paraprismatic-magma-wave","name":"Onda de Magma","originalName":"Magma Wave","aliases":[],"level":4,"school":"Conjuração","time":"1 ação","range":"linha de 9 metros","comp":"S","material":"","duration":"Instantânea","classes":"Cavaleiro Dracônico, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Uma onda de magma parte de você, preenchendo uma linha de 12 metros de comprimento e 6 metros de largura. Cada alvo nesse espaço deve realizar uma salvaguarda de Destreza, sofrendo 6d6 de dano de fogo em uma falha ou metade em um sucesso. O magma permanece preenchendo esses espaços e os transforma em terreno difícil por 1 minuto.\n\nQualquer criatura que comece o turno em um espaço preenchido por magma ou entre em um deles pela primeira vez no turno sofre 1d6 de dano de fogo. Cada espaço é considerado individualmente para esse efeito, embora criaturas maiores que entrem em vários ao mesmo tempo durante o movimento contem apenas um espaço por vez.\n\nQualquer espaço preenchido com um líquido que não seja quente/inflamável ou que cause dano de frio deixa de ser preenchido por magma.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º.","higher":"Quando você conjura esta magia no 5º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 4º:\n• O dano inicial aumenta em 1d6.\n• A onda fica 3 metros mais longa e 1,5 metro mais larga.\n• Você se torna imune aos efeitos do magma produzido por esta magia durante a duração dele.\n• O dano dos espaços preenchidos por magma aumenta para d8 (1 nível), d10 (2 níveis) ou d12 (3 níveis).","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":56,"category":"Paraprismatic Tempest","traits":["Burning Rites","Milarose’s Embodiments"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. A fonte imprime Range como uma linha de 30 pés, mas a descrição define a onda como 40 pés por 20 pés; ambos os valores foram preservados. A versão reimpressa em Zagalhta possui uma redação diferente no gatilho de escalonamento (“above 3rd”), portanto esta entrada permanece separada."},{"id":"paraprismatic-manipulate-flames","name":"Manipular Chamas","originalName":"Manipulate Flames","aliases":[],"level":0,"school":"Transmutação","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Instantânea ou 1 hora (veja abaixo)","classes":"Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Escolha uma chama não mágica que possa ver dentro do alcance e que caiba em um cubo de 1,5 metro. Você a afeta de uma das formas a seguir:\n• Expande instantaneamente a chama em 1,5 metro em uma direção, desde que madeira ou outro combustível esteja presente no novo local.\n• Extingue instantaneamente as chamas dentro do cubo.\n• Dobra ou reduz à metade a área de luz plena e penumbra emitida pela chama, muda sua cor, ou ambos. A alteração dura 1 hora.\n• Faz formas simples — como a aparência vaga de uma criatura, objeto inanimado ou local — surgirem nas chamas e se animarem como você desejar. As formas duram 1 hora.\n\nSe conjurar esta magia várias vezes, pode manter até três efeitos não instantâneos criados por ela ao mesmo tempo e pode encerrar um desses efeitos com uma ação.","higher":"","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":57,"category":"Paraprismatic Tempest","traits":["Burning Rites"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-nova","name":"Nova","originalName":"Nova","aliases":[],"level":8,"school":"Evocação","time":"1 ação","range":"90 metros","comp":"V, M (um orbe de vidro portátil)","material":"um orbe de vidro portátil","duration":"Concentração, até 1 minuto","classes":"Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Uma pequena estrela aparece em um ponto à sua escolha dentro do alcance. Ela é uma esfera de fogo e plasma com 4,5 metros de raio e libera uma onda de calor que afeta tudo em um raio de 18 metros de seu centro. Pelo restante da duração, os efeitos a seguir também ocorrem:\n\nChama Encarnada. Você é imune a dano de fogo pela duração e obtém sucesso automaticamente nas salvaguardas contra os efeitos desta magia.\n\nEvaporação. Todas as fontes não mágicas de água e gelo dentro do alcance de 18 metros da magia, assim como fontes mágicas produzidas por magias de nível inferior ao nível em que Nova foi conjurada, derretem e evaporam imediatamente, deixando vapor e áreas secas. Tudo dentro desse espaço é tratado como imune a dano de frio.\n\nExplosão de Fogo. Você pode produzir os efeitos de Bola de Fogo como uma ação em seu turno, sem gastar espaço de magia nem materiais. Ela é conjurada no nível-base, salvo indicação em contrário, e se origina do centro do espaço da estrela, portanto deve ser disparada a partir de até 45 metros desse ponto.\n\nOnda de Calor. Todos os materiais inflamáveis dentro do raio de 18 metros da magia se incendeiam. Criaturas que iniciarem o turno em espaços incendiados dessa forma ou entrarem em um deles no turno sofrem 2d6 de dano de fogo, e sofrem novamente cada vez que entram em um novo espaço. Criaturas usando materiais inflamáveis ou carregando itens inflamáveis devem realizar uma salvaguarda de Destreza ou ficam Incendiadas enquanto a magia durar. O dano da condição é igual ao dano de entrar em um espaço incendiado pela magia. Criaturas não podem apagar as chamas causadas pela Onda de Calor enquanto estiverem na área da magia.\n\nQueimadura Estelar. Criaturas que iniciarem o turno dentro do espaço da estrela ou entrarem nele pela primeira vez no turno devem realizar uma salvaguarda de Constituição, sofrendo 15d6 de dano de fogo em uma falha ou metade em um sucesso. Falhar nessa salvaguarda também conta como falhar na salvaguarda da Onda de Calor.","higher":"Quando você conjura esta magia no 9º nível, ela recebe os benefícios a seguir:\n• O espaço da estrela e o alcance de seus efeitos dobram.\n• Bola de Fogo conjurada por Explosão de Fogo passa a ser conjurada no 6º nível.\n• O dano da Onda de Calor aumenta em 2d6.\n• Escolha três outras criaturas dentro do alcance da magia ao conjurá-la. Elas também recebem os benefícios de Chama Encarnada.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":57,"category":"Paraprismatic Tempest","traits":["Burning Rites"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-place-protection","name":"Local de Proteção","originalName":"Place of Protection","aliases":[],"level":6,"school":"Abjuração","time":"10 minutos","range":"Toque","comp":"V, S, M (visco consumido pela magia, colhido com uma foice dourada sob a luz da lua cheia)","material":"visco consumido pela magia, colhido com uma foice dourada sob a luz da lua cheia","duration":"24 horas","classes":"Druida","ritual":false,"concentration":false,"desc":"Você invoca espíritos da natureza para proteger uma área ao ar livre ou subterrânea. A área pode ser tão pequena quanto um cubo de 9 metros ou tão grande quanto um cubo de 27 metros. Prédios e outras estruturas são excluídos da área afetada. Se você conjurar esta magia na mesma área todos os dias durante um ano, ela dura até ser dissipada.\n\nA magia cria os efeitos a seguir na área. Ao conjurá-la, você pode designar criaturas como amigas, tornando-as imunes aos efeitos. Também pode definir uma senha que, quando dita em voz alta, torna quem a pronunciar imune.\n\nToda a área protegida irradia magia. Uma Dissipar Magia conjurada na área, em caso de sucesso, remove apenas um dos efeitos abaixo, escolhido pelo conjurador de Dissipar Magia, e não a área inteira. A magia só é dissipada quando todos os efeitos forem removidos.\n\nNévoa Sólida. Você pode preencher qualquer número de quadrados de 1,5 metro no chão com névoa espessa, deixando-os fortemente obscurecidos. A névoa alcança 3 metros de altura. Além disso, cada 30 cm de movimento pela névoa custa 60 cm adicionais. Para uma criatura imune ao efeito, a névoa não obscurece nada e parece uma bruma suave com pontos de luz verde.\n\nVegetação Agarradora. Você pode preencher qualquer número de quadrados de 1,5 metro no chão que não estejam preenchidos com névoa por ervas daninhas e vinhas agarradoras, como se estivessem sob os efeitos de Emaranhar. Para criaturas imunes, a vegetação é macia e se remodela como assentos ou camas temporárias.\n\nGuardiões do Bosque. Você pode animar até quatro árvores na área, fazendo-as desenraizar. Elas usam as estatísticas de uma árvore desperta do Livro dos Monstros, exceto que não falam e sua casca é coberta por símbolos druídicos. Se uma criatura não imune entrar na área protegida, os guardiões lutam até expulsá-la ou matá-la. Também obedecem a comandos verbais que você der enquanto estiver na área, sem exigir ação. Sem comandos e sem intrusos, não fazem nada. Não podem deixar a área protegida. Quando a magia termina, a animação desaparece e as árvores criam raízes novamente, se possível.\n\nEfeito Mágico Adicional. Você pode colocar um dos efeitos mágicos a seguir na área protegida: uma Rajada de Vento constante em dois locais à sua escolha; Crescer Espinhos em um local à sua escolha; ou Muralha de Vento em dois locais à sua escolha. Para uma criatura imune a este efeito, os ventos são uma brisa suave e perfumada e a área de Crescer Espinhos é inofensiva.","higher":"","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":58,"category":"Paraprismatic Tempest","traits":["Harvest Tradition"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-scorching-wave","name":"Onda Escaldante","originalName":"Scorching Wave","aliases":[],"level":2,"school":"Evocação","time":"1 ação","range":"Pessoal (linha de 9 metros)","comp":"V, S, M (uma escama de dragão vermelho)","material":"uma escama de dragão vermelho","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Uma linha rugidora de chamas com 9 metros de comprimento e 1,5 metro de largura emana de você em uma direção à sua escolha. Cada criatura na linha deve realizar uma salvaguarda de Destreza, sofrendo 3d8 de dano de fogo em uma falha ou metade em um sucesso.","higher":"Quando você conjura esta magia no 3º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 2º:\n• O dano aumenta em 1d8.\n• A largura ou o comprimento da linha dobra.\n• (2 níveis) Qualquer criatura que falhar na salvaguarda fica Incendiada e, enquanto estiver Incendiada dessa forma, sofre dano de fogo da condição igual a 1d4 × o nível em que a magia foi conjurada.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":58,"category":"Paraprismatic Tempest","traits":["Burning Rites"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-sear","name":"Calcinar","originalName":"Sear","aliases":[],"level":5,"school":"Evocação","time":"1 ação","range":"27 metros","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Cavaleiro Dracônico, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Chamas envolvem uma criatura que você possa ver dentro do alcance. O alvo deve realizar uma salvaguarda de Destreza. Sofre 8d8 de dano de fogo em uma falha ou metade em um sucesso. Em uma falha, também fica Incendiado pela duração da magia, sofrendo 4d6 de dano da condição e emitindo luz plena em 9 metros e penumbra por mais 9 metros. Uma criatura Incendiada dessa forma repete a salvaguarda no início de cada um de seus turnos, encerrando o efeito em um sucesso, e não pode apagar as chamas por meios não mágicos. Se esta magia matar o alvo, ele é reduzido a cinzas.","higher":"Quando você conjura esta magia no 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 5º:\n• O dano de fogo primário aumenta em 1d8 e o dano de fogo secundário aumenta em 1d6.\n• Você pode escolher um alvo adicional dentro do alcance.\n• (2 níveis) Você não precisa se concentrar neste efeito.\n• (3 níveis) Como uma ação em cada um de seus turnos enquanto esta magia estiver em efeito, você pode escolher uma nova criatura dentro do alcance como se estivesse conjurando a magia novamente. A nova instância de seus efeitos fica vinculada à mesma duração.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":58,"category":"Paraprismatic Tempest","traits":["Burning Rites"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-tempest-strikes","name":"Golpes da Tempestade","originalName":"Tempest Strikes","aliases":[],"level":1,"school":"Evocação","time":"1 ação","range":"Pessoal","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Druida, Cavaleiro das Pétalas, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você canaliza o poder da tempestade, que permanece com você pela duração. Como ação bônus, pode realizar um único ataque corpo a corpo com magia contra um alvo a até 3 metros, ou um ataque à distância com magia contra um alvo a até 18 metros, causando 2d6 de dano de tempestade em um acerto.\n\nConhecimento Tempestuoso. Quando você aprende esta magia ou escolhe prepará-la, escolha um tipo de dano de tempestade. Sempre que a magia mencionar dano de tempestade, ela causa o tipo escolhido. Você pode aprender ou preparar esta magia várias vezes, escolhendo um tipo diferente em cada vez, e usar essas opções quando ela se referir a dano de tempestade.","higher":"Quando você conjura esta magia no 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 1º:\n• A magia causa 1d6 de dano de tempestade adicional.\n• O alcance do ataque à distância com magia dobra.\n• A duração aumenta até seu próximo Descanso Curto (1 nível) ou até seu próximo Descanso Longo (3 níveis).\n• (2 níveis) Você não precisa se concentrar nesta magia.\n• (2 níveis) Você realiza um ataque adicional contra um alvo dentro do alcance.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":60,"category":"Paraprismatic Tempest","traits":["Elemental Confluence"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."},{"id":"paraprismatic-tempest-ward","name":"Proteção da Tempestade","originalName":"Tempest Ward","aliases":[],"level":6,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Druida, Feiticeiro","ritual":false,"concentration":true,"desc":"Você tem resistência a dano de ácido, frio, fogo, elétrico e trovejante pela duração da magia.\n\nQuando sofre dano de um desses tipos, pode usar sua reação para ganhar imunidade a esse tipo, inclusive contra o dano que desencadeou a reação. Se fizer isso, todas as resistências terminam e você mantém a imunidade até o fim do seu próximo turno, quando a magia termina.","higher":"Quando você conjura esta magia no 7º nível ou superior, para cada nível acima do 6º pode escolher um tipo de dano adicional dentre os listados para tornar-se imune antes de perder suas resistências. Se conjurada no 9º nível, você se torna imune a todos eles ao conjurar a magia.","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":60,"category":"Paraprismatic Tempest","traits":["Elemental Confluence"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados. A lista desta magia usa trovejante e não veneno; isso foi preservado exatamente como impresso, apesar da definição geral de Tempest Damage do livro incluir veneno em vez de trovejante."},{"id":"paraprismatic-tornado","name":"Tornado","originalName":"Tornado","aliases":[],"level":8,"school":"Evocação","time":"1 ação","range":"90 metros","comp":"V, M (um pedaço de palha)","material":"um pedaço de palha","duration":"Concentração, até 1 minuto","classes":"Cavaleiro Dracônico, Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Um redemoinho desce sobre um ponto no chão que você possa ver dentro do alcance. O redemoinho é um cilindro de 6 metros de raio e 18 metros de altura centrado nesse ponto. Até a magia terminar, você pode usar sua ação para mover o redemoinho até 9 metros em qualquer direção ao longo do chão. Ele suga objetos Médios ou menores que não estejam presos a algo nem sendo vestidos ou carregados.\n\nUma criatura deve realizar uma salvaguarda de Destreza na primeira vez em um turno que entrar no redemoinho ou que o redemoinho entrar em seu espaço, inclusive quando ele surge. A criatura sofre 14d6 de dano contundente em uma falha ou metade em um sucesso. Além disso, uma criatura Grande ou menor que falhar deve ser bem-sucedida em uma salvaguarda de Força ou fica impedida dentro do redemoinho até a magia terminar. Quando uma criatura inicia o turno impedida pelo redemoinho, é puxada 1,5 metro para cima, salvo se já estiver no topo. Uma criatura impedida se move junto com o redemoinho e cai quando a magia termina, salvo se tiver outro meio de permanecer no ar.\n\nUma criatura impedida pode usar uma ação para realizar um teste de Força ou Destreza contra sua CD de magia. Em caso de sucesso, deixa de ficar impedida pelo redemoinho e é arremessada 6d6 × 3 metros para longe dele em uma direção aleatória.","higher":"","source":"Somnus Domina — Paraprismatic Tempest","sourcePage":60,"category":"Paraprismatic Tempest","traits":["Twisting Gale Path"],"sourceNote":"Versão apresentada no capítulo Tempestuous Spells de Paraprismatic Tempest; texto, escalonamento 5.19 e terminologia da fonte foram preservados."}];

window.GRIMORIO_REGISTRY.registerSpellCatalog({id:'paraprismatic-tempest-spells',sourceId:'paraprismatic-tempest',spells:window.GRIMORIO_PARAPRISMATIC_SPELLS});

(function linkParaprismaticReprints(){
  const SOURCE = 'Somnus Domina — Paraprismatic Tempest';
  const refs = [{"id":"bbb-cross-handle","originalName":"Cross Handle","sourcePage":52,"groups":["Zanjen"],"note":"Reimpresso integralmente em Paraprismatic Tempest p. 52; mantida uma única entrada pesquisável para não duplicar um bloco mecanicamente equivalente."},{"id":"lyre-manipulate-earth","originalName":"Manipulate Earth","sourcePage":57,"groups":["Harvest Tradition"],"note":"Reimpresso integralmente em Paraprismatic Tempest p. 57; mantida uma única entrada pesquisável para não duplicar um bloco mecanicamente equivalente."}];
  const catalogs = window.GRIMORIO_REGISTRY.getSpellCatalogs();
  const byId = new Map();
  for (const catalog of catalogs) for (const spell of (catalog.spells || [])) byId.set(spell.id, spell);
  for (const ref of refs) {
    const spell = byId.get(ref.id);
    if (!spell) continue;
    spell.otherSources = spell.otherSources || [];
    if (!spell.otherSources.some(entry => entry && entry.title === SOURCE)) {
      spell.otherSources.push({title:SOURCE,pages:String(ref.sourcePage),note:ref.note});
    }
    spell.traits = Array.from(new Set([...(spell.traits || []), ...(ref.groups || [])]));
  }
  window.GRIMORIO_PARAPRISMATIC_SPELL_REPRINTS = refs;
})();
